/**
 * Example investigations for the landing page.
 *
 * The numbers come from `cases.json`, generated by scripts/landing_cases.py
 * from offline runs of the synthetic demo samples through the real engines;
 * a backend test fails if they drift. Only the one-line blurbs are written
 * here, and they describe what those runs found.
 */
import data from '@/components/landing/cases.json';
import type { Colour } from '@/components/landing/palette';
import type { RiskLevel } from '@/types/api';

export interface Case {
  id: string;
  title: string;
  sub: string;
  colour: Colour;
  type: string;
  content: string;
  score: number;
  level: RiskLevel;
  classification: string;
  signals: { title: string; points: number; evidence: string }[];
}

export const CASES = data as Case[];

